def build_vocab():
    unique_words, all_words = [], []
    for line in open('data/jaychou_lyrics.txt', 'r', encoding='utf-8'):
        words = jieba.lcut(line)
        all_words.append(words)                    # 含重复
        for word in words:
            if word not in unique_words:
                unique_words.append(word)          # 去重（保留顺序）
    word_count = len(unique_words)
    word_to_index = {word: idx for idx, word in enumerate(unique_words)}
    corpus_idx = []
    for words in all_words:
        temp = [word_to_index[w] for w in words]
        temp.append(word_to_index[' '])            # 每行词之间用空格隔开
        corpus_idx.extend(temp)                    # 全语料一维编号序列
    return unique_words, word_to_index, word_count, corpus_idx

class TextGenerator(nn.Module):
    def __init__(self, unique_word_count):
        super().__init__()
        self.ebd = nn.Embedding(unique_word_count, 128)   # 词向量维度 128
        self.rnn = nn.RNN(128, 256, 1)                    # 词向量 128 → 隐藏 256，1 层
        self.out = nn.Linear(256, unique_word_count)      # 输出词表中每个词的分值

    def forward(self, inputs, hidden):
        embed = self.ebd(inputs)                                  # (batch, seq_len, 128)
        output, hidden = self.rnn(embed.transpose(0, 1), hidden)  # RNN 默认需 (seq_len, batch, 128)
        output = self.out(output.reshape(shape=(-1, output.shape[-1])))   # (seq_len*batch, 词表大小)
        return output, hidden

    def init_hidden(self, bs):
        return torch.zeros(1, bs, 256)     # [网络层数, batch, 隐藏层维度]

class Embedding(nn.Module):
    def __init__(self, d_model, vocab_size):
        super().__init__()
        self.lut = nn.Embedding(vocab_size, d_model, padding_idx=2)   # PAD=2 行默认置零
        self.d_model = d_model
    def forward(self, x):
        return self.lut(x) * math.sqrt(self.d_model)   # [B,L] → [B,L,D]；乘 √D 与位置编码尺度对齐

def attention(query, key, value, dropout=None, mask=None):
    d_k = query.size(-1)
    scores = torch.matmul(query, key.transpose(-2, -1)) / math.sqrt(d_k)   # Q@K^T / √dk
    if mask is not None:
        scores = scores.masked_fill(mask == 0, -1e9)
    p_attn = F.softmax(scores, dim=-1)
    if dropout is not None:
        p_attn = dropout(p_attn)
    return torch.matmul(p_attn, value), p_attn

class PositionwiseFeedForward(nn.Module):
    def __init__(self, d_model, d_ff, dropout=0.1):
        super().__init__()
        self.w1 = nn.Linear(d_model, d_ff)
        self.w2 = nn.Linear(d_ff, d_model)
        self.dropout = nn.Dropout(p=dropout)
    def forward(self, x):
        return self.w2(self.dropout(F.relu(self.w1(x))))   # [B,L,D] → [B,L,d_ff] → [B,L,D]

class LayerNorm(nn.Module):
    def __init__(self, features, eps=1e-6):
        super().__init__()
        self.a2 = nn.Parameter(torch.ones(features))    # 缩放因子（控制方差）
        self.b2 = nn.Parameter(torch.zeros(features))   # 平移因子（控制均值）
        self.eps = eps
    def forward(self, x):
        mean = x.mean(dim=-1, keepdim=True)             # 对每个位置的所有特征维度求均值
        var  = x.var(dim=-1, keepdim=True, unbiased=False)
        x = (x - mean) / torch.sqrt(var + self.eps)     # eps 放在平方根内部
        return self.a2 * x + self.b2

class EncoderLayer(nn.Module):
    def forward(self, x, mask=None):
        # 1 自注意力：Q、K、V 来自同一份输入；编码器通常双向关注，只屏蔽源 PAD
        x = self.sublayer[0](x, lambda z: self.self_attn(z, z, z, mask))
        # 2 FFN：逐位置加工，形状保持 [B, S, D]
        return self.sublayer[1](x, self.ffn)

class DecoderLayer(nn.Module):
    def forward(self, x, memory, source_mask, target_mask):
        # 1 因果自注意力：只关注已有目标前缀
        x = self.sublayer[0](x, lambda z: self.self_attn(z, z, z, target_mask))
        # 2 交叉注意力：Q 来自目标侧，K、V 来自 memory
        x = self.sublayer[1](x, lambda z: self.src_attn(z, memory, memory, source_mask))
        # 3 FFN
        return self.sublayer[2](x, self.ffn)

class Generator(nn.Module):
    def __init__(self, d_model, vocab_size):
        super().__init__()
        self.project = nn.Linear(d_model, vocab_size)
    def forward(self, x):
        return F.log_softmax(self.project(x), dim=-1)

